/bin/zsh -lc "python3 -c 'import csv,json
from pathlib import Path
p=Path(\"project\")
codes=json.loads((p/\"status-code-contract.json\").read_text())[\"status_codes\"]
expected={}
for r in csv.DictReader((p/\"commits.csv\").open()):
    if r[\"result\"] "'!= "committed": continue
    if r["operation"] == "delete": expected.pop(r["key"],None)
    else: expected[r["key"]]=(r["incarnation"],r["revision"],str(codes[r["status_text"]]),r["revision"])
actual={r["key"]:(r["incarnation"],r["source_rev"],r["status_code"],r["mapped_rev"]) for r in csv.DictReader((p/"derived.csv").open())}
print("expected:",expected)
print("actual:",actual)
print("missing:",sorted(expected.keys()-actual.keys()))
print("extra:",sorted(actual.keys()-expected.keys()))
print("shared_mismatches:",{k:(expected[k],actual[k]) for k in expected.keys() & actual.keys() if expected[k]!=actual[k]})'"'"

